package studio.jiayu.neoagent;
import android.app.Activity;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.concurrent.atomic.*;
/** Actual Android gestures against an owned synthetic shop. Never creates a merchant order. */
final class PurchaseContracts {
 final Activity a;final ControlService s;final boolean viaMcp;final AtomicInteger submitted=new AtomicInteger(),paid=new AtomicInteger();TextView money;int passed;String time;
 PurchaseContracts(Activity a){this.a=a;s=ControlService.instance;viaMcp="purchase_mcp".equals(a.getIntent().getStringExtra("mode"));}
 static void start(Activity a){PurchaseContracts test=new PurchaseContracts(a);test.confirm("5.01");new Handler().postDelayed(()->new Thread(test::run).start(),700);}
 LinearLayout page(String title,String total){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(40,140,40,30);box.setBackgroundColor(0xFF202126);a.setContentView(box);label(box,title);label(box,"商品：百洁布一包");label(box,"数量：1");money=label(box,"实付款：￥"+total+"（含运费）");label(box,"收货地址：本地合成收件地址");return box;}
 TextView label(LinearLayout box,String text){TextView v=new TextView(a);v.setText(text);v.setTextSize(16);v.setTextColor(0xFFEFEFF0);v.setPadding(0,12,0,12);box.addView(v);return v;}
 void button(LinearLayout box,String label,Runnable action){Button b=new Button(a);b.setText(label);b.setOnClickListener(v->action.run());box.addView(b);}
 void confirm(String total){LinearLayout box=page("确认订单",total);button(box,"提交订单",()->{submitted.incrementAndGet();time=java.time.ZonedDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));receipt(false);});button(box,"确定，需支付4.99元",()->submitted.incrementAndGet());}
 void receipt(boolean payment){LinearLayout box=page(payment?"支付成功":"订单提交成功","4.99");label(box,"订单号：FIXTURE-ORDER-0001");label(box,"下单时间："+time);if(!payment)button(box,"查看收银台",this::cashier);}
 void cashier(){LinearLayout box=page("收银台","4.99");label(box,"订单号：FIXTURE-ORDER-0001");button(box,"立即支付",()->{paid.incrementAndGet();receipt(true);});}
 void yes(boolean ok,String reason)throws Exception{if(!ok)throw new Exception(reason);passed++;}
 int id(ControlService.Observation o,String label)throws Exception{JSONArray nodes=o.json.getJSONArray("nodes");for(int i=0;i<nodes.length();i++)if(label.equals(nodes.getJSONObject(i).optString("text")))return nodes.getJSONObject(i).getInt("id");throw new Exception("Missing synthetic native button: "+label);}
 Action action(String kind,int id)throws Exception{return new Action(new JSONObject().put("action",kind).put("id",id));}
 String execute(Action action,long g,ControlService.Observation o)throws Exception{return viaMcp?s.deviceMcp.invoke(action,g,o):s.execute(action,g,o);}
 void denied(Action action,long g,ControlService.Observation o)throws Exception{boolean blocked=false;try{execute(action,g,o);}catch(Exception expected){blocked=true;}yes(blocked,"Unverified financial action executed");}
 void run(){JSONObject result=new JSONObject();String oldGrant="",oldLedger="",oldOutcome="";PurchaseRuntime oldRuntime=null;try{
  yes(s!=null&&s.connected&&!s.busy(),"Runtime not idle");oldRuntime=s.purchase;oldGrant=new Vault(a).get(RoutineAccess.KEY);oldOutcome=new Vault(a).get("last-outcome");Config cfg=new Config();cfg.key="LOCAL_SYNTHETIC_ONLY";cfg.endpoint="https://purchase-fixture.invalid";new RoutineAccess(a).approve(cfg,java.util.Collections.singletonList(a.getPackageName()));PurchaseRuntime runtime=new PurchaseRuntime(s,true);oldLedger=runtime.ledger.raw();runtime.ledger.raw("");
  long g=s.ui(()->{s.purchase=runtime;s.workflow=null;s.allowed=a.getPackageName();s.runConfig=cfg;s.task="合成订单测试，不创建任何真实订单";s.runId="purchase-fixture-run";s.ownerSession="";s.activeRequest=new TaskRequest(s.allowed,"只看价格，不购买","",false);s.running=true;s.paused=false;s.generation=s.ownership.start();s.checkout=true;s.activeSince=SystemClock.elapsedRealtime();s.activeMillis=0;s.startedAt=System.currentTimeMillis();s.runtimeHealth.phase("waiting");return s.generation;});
  if(viaMcp){s.deviceMcp.reset();s.deviceMcp.activate(s.allowed,g);}
  boolean invalid=false;try{Action.parse("{\"action\":\"purchase_submit\",\"x\":500,\"y\":900}");}catch(Exception expected){invalid=true;}yes(invalid,"Financial coordinate action accepted");
  ControlService.Observation first=CaptureContracts.stable(s,g);int submit=id(first,"提交订单");denied(action("purchase_submit",submit),g,first);yes(submitted.get()==0,"No-grant submitted");
  s.ui(()->{s.activeRequest=new TaskRequest(s.allowed,"帮我正式购买一件5块钱内的物品看看流程是否跑通京东淘宝","",false);return true;});Thread.sleep(450);ControlService.Observation capped=CaptureContracts.stable(s,g);denied(action("tap",id(capped,"提交订单")),g,capped);yes(submitted.get()==0,"Ordinary tap bypassed financial guard");android.graphics.Rect wide=new android.graphics.Rect();capped.targets.get(id(capped,"确定，需支付4.99元")).getBoundsInScreen(wide);android.util.DisplayMetrics dm=s.screenMetrics();yes(wide.width()>dm.widthPixels*.8,"Fixture payment control not full width");denied(Action.parse("{\"action\":\"tap\",\"x\":"+(wide.centerX()*1000/dm.widthPixels)+",\"y\":"+(wide.centerY()*1000/dm.heightPixels)+"}"),g,capped);yes(submitted.get()==0,"Full-width ambiguous payment bypassed coordinate guard");denied(action("purchase_submit",id(capped,"提交订单")),g,capped);yes(runtime.ledger.load().state.equals(PurchaseState.EMPTY)&&submitted.get()==0,"Over-cap touched or consumed quota");
  s.ui(()->{money.setText("实付款：￥4.99（含运费）");return true;});Thread.sleep(400);ControlService.Observation quoted=CaptureContracts.stable(s,g);s.ui(()->{money.setText("实付款：￥5.01（含运费）");return true;});Thread.sleep(250);denied(action("purchase_submit",id(quoted,"提交订单")),g,quoted);yes(submitted.get()==0,"Price changed after screenshot was ignored");
  s.ui(()->{money.setText("实付款：￥4.99（含运费）");return true;});Thread.sleep(400);ControlService.Observation valid=CaptureContracts.stable(s,g);execute(action("purchase_submit",id(valid,"提交订单")),g,valid);Thread.sleep(450);yes(submitted.get()==1&&paid.get()==0,"Wrong number of native submit callbacks");JSONObject status=s.ui(runtime::status);yes(status.optBoolean("order_created_verified")&&!status.optBoolean("paid_verified"),"Created order counted as paid");yes(runtime.ledger.load().state.equals(PurchaseState.ORDER_VERIFIED),"Native order not reconciled");
  PurchaseRuntime reloaded=new PurchaseRuntime(s,true);s.purchase=reloaded;yes(reloaded.ledger.load().state.equals(PurchaseState.ORDER_VERIFIED),"Encrypted state lost on adapter restart");String encrypted=a.getSharedPreferences("vault",0).getString(reloaded.ledger.key,"");yes(!encrypted.contains("百洁布")&&!encrypted.contains("收件地址"),"Plaintext transaction record");
  denied(action("purchase_submit",id(valid,"提交订单")),g,valid);yes(submitted.get()==1,"Old action replayed after restore");ControlService.Observation created=CaptureContracts.stable(s,g);execute(action("tap",id(created,"查看收银台")),g,created);Thread.sleep(450);
  ControlService.Observation cash=CaptureContracts.stable(s,g);s.ui(()->{money.setText("实付款：￥5.01（含运费）");return true;});Thread.sleep(250);denied(action("purchase_pay",id(cash,"立即支付")),g,cash);yes(paid.get()==0,"Changed payment total accepted");
  s.ui(()->{money.setText("实付款：￥4.99（含运费）");return true;});Thread.sleep(400);cash=CaptureContracts.stable(s,g);execute(action("purchase_pay",id(cash,"立即支付")),g,cash);Thread.sleep(450);yes(paid.get()==1,"Native payment gesture failed");yes(s.ui(reloaded::status).optBoolean("paid_verified")&&reloaded.complete(),"Native paid receipt not matched");denied(action("purchase_pay",id(cash,"立即支付")),g,cash);yes(paid.get()==1&&submitted.get()==1,"Duplicate financial action");
  yes(s.purchase.synthetic,"Fixture mistaken for real purchase");result.put("success",true).put("via_mcp",viaMcp);if(viaMcp)result.put("mcp",s.deviceMcp.status());
 }catch(Throwable error){try{result.put("success",false).put("failure",error.getMessage()).put("where",java.util.Arrays.toString(error.getStackTrace()).substring(0,Math.min(800,java.util.Arrays.toString(error.getStackTrace()).length())));}catch(Exception ignored){}}
 finally{try{if(s!=null){s.stop("合成小额购买回归结束 · 零真实订单");if(oldRuntime!=null&&s.purchase.synthetic){s.purchase.ledger.raw(oldLedger);s.purchase=oldRuntime;}}new Vault(a).put(RoutineAccess.KEY,oldGrant);new Vault(a).put("last-outcome",oldOutcome);result.put("passed",passed).put("native_submit_callbacks",submitted.get()).put("native_pay_callbacks",paid.get()).put("real_orders",0).put("real_payments",0).put("real_network_calls",0).put("synthetic",true).put("sampledAt",System.currentTimeMillis());try(FileOutputStream out=a.openFileOutput(viaMcp?"purchase-mcp-contracts.json":"purchase-contracts.json",0)){out.write(result.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}new Handler(Looper.getMainLooper()).post(a::finish);}
 }
}
